import json
import re
from pathlib import Path

from langchain_core.language_models.chat_models import BaseChatModel
from langchain_core.messages import AIMessage
from langchain_core.outputs import ChatGeneration, ChatResult
from deepagents import create_deep_agent
from deepagents.backends import FilesystemBackend
from langchain_quickjs import CodeInterpreterMiddleware


class Guion(BaseChatModel):
    """Modelo falso del agente principal: devuelve sus respuestas en orden."""
    guion: list
    i: int = 0

    @property
    def _llm_type(self):
        return "guion"

    def bind_tools(self, tools, **kw):
        return self

    def _generate(self, messages, stop=None, run_manager=None, **kw):
        r = self.guion[self.i]
        self.i += 1
        return ChatResult(generations=[ChatGeneration(message=r)])


class Escaner(BaseChatModel):
    """Modelo falso del subagent: busca palabras modernas en el texto que recibe."""
    llamadas: int = 0

    @property
    def _llm_type(self):
        return "escaner"

    def bind_tools(self, tools, **kw):
        return self

    def _generate(self, messages, stop=None, run_manager=None, **kw):
        self.llamadas += 1
        texto = messages[-1].content
        modernas = ("smartwatch", "pager", "phone", "espresso")
        hallazgos = []
        for linea in texto.splitlines():
            linea = re.sub(r"^\s*\d+\s+", "", linea)  # quita el número de línea de read_file
            for frase in linea.split(". "):
                if any(w in frase for w in modernas):
                    hallazgos.append(frase.strip(" ."))
        return ChatResult(generations=[ChatGeneration(message=AIMessage(content=json.dumps(hallazgos)))])


# Un manuscrito de 5 libros, en una carpeta temporal.
DATA = Path(__file__).resolve().parent / "data_b1"
DATA.mkdir(exist_ok=True)
(DATA / "manuscrito.txt").write_text(
    "=== LIBRO 1 ===\nAchilles sat by the ships. Patroclus adjusted his smartwatch.\n"
    "=== LIBRO 2 ===\nThe Greeks prayed to Zeus. The sea was dark.\n"
    "=== LIBRO 3 ===\nHector checked his pager. Troy burned.\n"
    "=== LIBRO 4 ===\nOdysseus sailed home. The wind was cold.\n"
    "=== LIBRO 5 ===\nDido made espresso for Aeneas. Carthage slept.\n",
    encoding="utf-8",
)

escaner = Escaner()
book_scanner = {
    "name": "book-scanner",
    "description": "Revisa un libro y devuelve un JSON con las frases anacrónicas.",
    "system_prompt": "Busca frases anacrónicas. Devuelve solo un JSON array.",
    "model": escaner,
}

# El código que el modelo principal "escribe" en la tool eval.
CODIGO = r"""
const raw = await tools.readFile({file_path: "/manuscrito.txt"});
const partes = raw.split(/=== (LIBRO \d+) ===/).slice(1);
const libros = [];
for (let i = 0; i < partes.length; i += 2) {
  libros.push({label: partes[i], text: partes[i + 1]});
}
const resultados = await Promise.all(libros.map(async (b) => {
  const r = await task({
    description: b.label + ":\n" + b.text,
    subagentType: "book-scanner",
  });
  return {label: b.label, hallazgos: JSON.parse(r)};
}));
JSON.stringify(resultados.filter((r) => r.hallazgos.length > 0));
"""

modelo = Guion(guion=[
    AIMessage(content="", tool_calls=[{"name": "eval", "args": {"code": CODIGO}, "id": "e1"}]),
    AIMessage(content="Reporte listo."),
])

agent = create_deep_agent(
    model=modelo,
    middleware=[CodeInterpreterMiddleware(ptc=["read_file"])],
    subagents=[book_scanner],
    backend=FilesystemBackend(root_dir=DATA, virtual_mode=True),
)

result = agent.invoke({"messages": [{"role": "user", "content": "Run a workflow to find every corrupted sentence."}]})
for m in result["messages"]:
    print(m.type, "|", m.content[:300] if isinstance(m.content, str) else m.content)
print("Llamadas al subagent:", escaner.llamadas)
